function toUtcRange(dateStr, localStartHHMM, hours) {
  if (!dateStr) throw new Error('Missing date');
  if (!localStartHHMM) throw new Error('Missing shift start');
  if (hours === undefined || hours === null || Number.isNaN(Number(hours))) {
    throw new Error('Missing or invalid hours');
  }

  const [year, month, day] = String(dateStr).split('-').map(Number);
  const [startHour, startMinute] = String(localStartHHMM).split(':').map(Number);

  if (![year, month, day, startHour, startMinute].every(Number.isFinite)) {
    throw new Error(`Invalid date/time. date=${dateStr}, shiftStart=${localStartHHMM}`);
  }

  // Phoenix is UTC-7 year-round
  const startUtc = new Date(Date.UTC(year, month - 1, day, startHour + 7, startMinute, 0));
  const endUtc = new Date(startUtc.getTime() + Number(hours) * 60 * 60 * 1000);

  return {
    start: startUtc.toISOString().replace('.000Z', 'Z'),
    end: endUtc.toISOString().replace('.000Z', 'Z'),
  };
}

function buildDeterministicOffset(seed, modulo) {
  if (!modulo || modulo < 1) return 0;
  let hash = 0;
  const str = String(seed);
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash) % modulo;
}

const config = $json;

const date = config.date;
const roster = Array.isArray(config.members) ? config.members : [];
const shifts = Array.isArray(config.shifts) ? config.shifts : [];
const customers = Array.isArray(config.customers) ? config.customers.filter(c => c && c.billable) : [];
const dailyHours = config.dailyHours || { billable: 8, admin: 2 };
const allowedBillingMap = config.allowedBillingMap || {};

if (!date) throw new Error('Missing top-level date');
if (!roster.length) throw new Error('No roster members found');
if (!shifts.length) throw new Error('No shifts found');
if (!customers.length) throw new Error('No billable customers found');

const weekday = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Phoenix',
  weekday: 'short'
}).format(new Date(`${date}T12:00:00Z`));

const rosterById = Object.fromEntries(
  roster.map(member => [String(member.memberId), member])
);

const customerById = Object.fromEntries(
  customers.map(customer => [String(customer.companyId), customer])
);

const scheduled = [];

for (const shift of shifts) {
  for (const shiftMember of (shift.members || [])) {
    const worksToday = Array.isArray(shiftMember.days) && shiftMember.days.includes(weekday);
    if (!worksToday) continue;

    const fullMember = rosterById[String(shiftMember.memberId)] || shiftMember;

    scheduled.push({
      date,
      weekday,
      shiftName: shift.name,
      shiftStart: shift.start,
      shiftEnd: shift.end,
      memberId: fullMember.memberId,
      identifier: fullMember.identifier,
      name: fullMember.name,
      title: fullMember.title || null,
      workRoleId: fullMember.workRoleId,
      workTypeId: fullMember.workTypeId ?? config.workTypeId,
      locationId: fullMember.locationId ?? config.locationId,
      businessUnitId: config.businessUnitId,
      chargeToType: config.chargeToType,
      chargeToId: config.chargeToId,
      internalCompanyId: config.companyId,
      dailyBillable: Number(fullMember.dailyBillable ?? dailyHours.billable),
      dailyAdmin: Number(fullMember.dailyAdmin ?? dailyHours.admin),
    });
  }
}

if (!scheduled.length) {
  return [];
}

scheduled.sort((a, b) =>
  String(a.identifier || a.name || a.memberId).localeCompare(
    String(b.identifier || b.name || b.memberId)
  )
);

const results = [];

for (const analyst of scheduled) {
  const memberKey = String(analyst.memberId);
  const allowedCompanyIds = Array.isArray(allowedBillingMap[memberKey])
    ? allowedBillingMap[memberKey].map(id => String(id))
    : [];

  const allowedCustomers = allowedCompanyIds
    .map(id => customerById[id])
    .filter(Boolean);

  const billableHours = analyst.dailyBillable;
  const adminHours = analyst.dailyAdmin;

  const billableRange = toUtcRange(analyst.date, analyst.shiftStart, billableHours);
  const fullRange = toUtcRange(analyst.date, analyst.shiftStart, billableHours + adminHours);

  if (allowedCustomers.length > 0 && billableHours > 0) {
    const offset = buildDeterministicOffset(`${date}-${memberKey}`, allowedCustomers.length);
    const client = allowedCustomers[offset];

    results.push({
      json: {
        memberId: analyst.memberId,
        name: analyst.name,
        identifier: analyst.identifier,
        weekday: analyst.weekday,
        shiftName: analyst.shiftName,
        type: 'billable',
        clientCompanyId: client.companyId,
        clientName: client.name,
        body: {
          company: { id: client.companyId },
          chargeToType: analyst.chargeToType || 'ChargeCode',
          chargeToId: analyst.chargeToId,
          member: { id: analyst.memberId },
          locationId: analyst.locationId,
          businessUnitId: analyst.businessUnitId,
          workType: { id: analyst.workTypeId },
          workRole: { id: analyst.workRoleId },
          timeStart: billableRange.start,
          timeEnd: billableRange.end,
          actualHours: billableHours,
          billableOption: 'Billable',
          notes: `${analyst.shiftName} shift SOC coverage`,
          addToDetailDescriptionFlag: false,
          addToInternalAnalysisFlag: false,
          addToResolutionFlag: false,
        },
      },
    });
  } else {
    results.push({
      json: {
        memberId: analyst.memberId,
        name: analyst.name,
        identifier: analyst.identifier,
        weekday: analyst.weekday,
        shiftName: analyst.shiftName,
        type: 'admin',
        clientCompanyId: analyst.internalCompanyId,
        clientName: 'Internal Admin',
        body: {
          company: { id: analyst.internalCompanyId },
          chargeToType: analyst.chargeToType || 'ChargeCode',
          chargeToId: analyst.chargeToId,
          member: { id: analyst.memberId },
          locationId: analyst.locationId,
          businessUnitId: analyst.businessUnitId,
          workType: { id: analyst.workTypeId },
          workRole: { id: analyst.workRoleId },
          timeStart: billableRange.start,
          timeEnd: fullRange.end,
          actualHours: billableHours + adminHours,
          billableOption: 'DoNotBill',
          notes: `${analyst.shiftName} shift internal SOC coverage`,
          addToDetailDescriptionFlag: false,
          addToInternalAnalysisFlag: false,
          addToResolutionFlag: false,
        },
      },
    });

    continue;
  }

  if (adminHours > 0) {
    results.push({
      json: {
        memberId: analyst.memberId,
        name: analyst.name,
        identifier: analyst.identifier,
        weekday: analyst.weekday,
        shiftName: analyst.shiftName,
        type: 'admin',
        clientCompanyId: analyst.internalCompanyId,
        clientName: 'Internal Admin',
        body: {
          company: { id: analyst.internalCompanyId },
          chargeToType: analyst.chargeToType || 'ChargeCode',
          chargeToId: analyst.chargeToId,
          member: { id: analyst.memberId },
          locationId: analyst.locationId,
          businessUnitId: analyst.businessUnitId,
          workType: { id: analyst.workTypeId },
          workRole: { id: analyst.workRoleId },
          timeStart: billableRange.end,
          timeEnd: fullRange.end,
          actualHours: adminHours,
          billableOption: 'DoNotBill',
          notes: `${analyst.shiftName} shift admin`,
          addToDetailDescriptionFlag: false,
          addToInternalAnalysisFlag: false,
          addToResolutionFlag: false,
        },
      },
    });
  }
}

return results;
